import type { HeroBrandMarkOwnerProps } from '@deepseek-ai/dsh-client-ui-conversation/client'
import type { SidebarBrandMarkOwnerProps } from '@deepseek-ai/dsh-client-ui-sidebar/client'

type HaowiseBrandMarkProps = HeroBrandMarkOwnerProps & SidebarBrandMarkOwnerProps

/** HAOWISE light-variant wordmark PNG (public-path asset). */
const HW_LIGHT = 'data:image/png;base64,'

/** HAOWISE dark-variant wordmark PNG (public-path asset). */
const HW_DARK = 'data:image/png;base64,'

/**
 * Render the HAOWISE Λ monogram mark.
 * The viewBox is 23.16×17.04 so callers that size by width keep their layout.
 * @param props.size - width in px (default 24).
 * @param props.className - extra class for layout placement.
 * @returns the monogram svg (aria-hidden; pair with the wordmark for accessibility).
 */
export function HaowiseBrandMark({ size = 24, className }: HaowiseBrandMarkProps) {
  return (
    <svg
      width={size}
      height={(size * 17.04) / 23.16}
      className={className}
      viewBox="0 0 23.16 17.04"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M11.58 1.6 2.6 15.5M11.58 1.6l8.98 13.9"
        stroke="#1F5FA0"
        strokeWidth="3.3"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/**
 * Render the HAOWISE wordmark as a span with light/dark PNG variants.
 * Theme-swap rules (.hw-wordmark, .hw-logo, .hw-light, .hw-dark) live in
 * design-platform.css so callers need not know about them.
 * @param props.size - height in px (default 24).
 * @param props.className - extra class for layout placement.
 * @returns the wordmark element (aria-label "HAOWISE").
 */
export function HaowiseBrandName({ size = 24, className }: {
  size?: number
  className?: string
}) {
  const cls = ['hw-wordmark', className].filter(Boolean).join(' ')
  return (
    <span className={cls} role="img" aria-label="HAOWISE">
      <img
        className="hw-logo hw-light"
        src={HW_LIGHT}
        alt=""
        aria-hidden="true"
        style={{ height: size }}
      />
      <img
        className="hw-logo hw-dark"
        src={HW_DARK}
        alt=""
        aria-hidden="true"
        style={{ height: size }}
      />
    </span>
  )
}
